    signedDispatchRecorded:!!events['signed-dispatch'],
    signedResponseRecorded:!!events['signed-response'],
    ...(nativeSigning ? {nativeSigning} : {}),
    records:Object.fromEntries(Object.entries(events).map(([name, item]) =>
      [name, {path:join(directory, name + '.json'),sha256:item.sha256,bytes:item.bytes,
        recordedAt:item.value.recordedAt}])),
    response:events['signed-response'] ? {
      status:events['signed-response'].value.status,
      headersSha256:valueHash(events['signed-response'].value.headers),
    } : null,
  };
}

/** Called once by original execute before the buyer/approval/signer can run.
 * All wire payloads remain in the caller's existing private evidence directory.
 * No socket, signer, approval or ledger capability is provided by this module. */
export async function createAttemptWireRecorder({cfg, body, fetchImpl, reserveFile, signal}) {
  need(typeof fetchImpl === 'function', 'WIRE_ORIGINAL_TRANSPORT_REQUIRED');
  const frozen = JSON.parse(JSON.stringify(cfg));
  const originalBody = requestBody(body);
  const binding = bindingFor(frozen, originalBody);
  await privateDirectory(frozen.evidenceDir, {create:false});
  const directory = await privateDirectory(wirePath(frozen));
  const sourceValue = {
    schema:SCHEMA, binding, recordedAt:now(), config:frozen,
    requestBodyBase64:originalBody.present ? originalBody.bytes.toString('base64') : null,
  };
  const sourceRaw = jsonBytes(sourceValue);
  need(sourceRaw.length <= SOURCE_LIMIT, 'WIRE_SOURCE_TOO_LARGE');
  const held = await ownership(directory,true);
  need(held,'WIRE_ATTEMPT_ACTIVE');
  let reservations;
  try {
    // These are the actual future checkpoint inodes, held before approval or signing.
    reservations = await prepareWriteReservations([
      {path:join(directory,'source.json'),bytes:sourceRaw.length,exclusive:true},
      ...EVENTS.map(name=>({path:join(directory,name+'.json'),bytes:RECORD_LIMIT,exclusive:true})),
    ], {reserveFile,signal});
    if (reservations) await reservations.writeBytes(join(directory,'source.json'),sourceRaw,{exclusive:true});
    else await writeBytes(join(directory,'source.json'),sourceRaw,{exclusive:true});
  } catch (error) {
    try { await reservations?.close(); } finally { await held.close(); }
    if (error.code === 'EEXIST') throw new BuyerError('WIRE_ATTEMPT_ALREADY_RECORDED_USE_RECOVERY');
    throw error;
  }
  const source = {raw:sourceRaw, value:sourceValue, sha256:digest(sourceRaw),bytes:sourceRaw.length};
  const events = Object.create(null);
  let closed=false;
  async function publish(name, fields) {
    need(!closed && EVENTS.includes(name) && !events[name], 'WIRE_PHASE_ALREADY_RECORDED');
    const raw = jsonBytes({schema:SCHEMA, intentId:binding.intentId, sourceSha256:source.sha256,
      phase:name, recordedAt:now(), ...fields});
    const value = parseJson(raw);
    need(raw.length <= RECORD_LIMIT, 'WIRE_RECORD_TOO_LARGE');
    if (reservations) await reservations.writeBytes(join(directory,name+'.json'),raw,{exclusive:true});
    else await writeBytes(join(directory,name+'.json'),raw,{exclusive:true});
    events[name] = {raw,value,sha256:digest(raw),bytes:raw.length};
    return events[name];
  }
  async function signingInput(input) {
    need(input?.intent?.intentId === binding.intentId && input.intent.url === binding.url &&
      input.intent.method === binding.method && input.intent.bodyPresent === binding.bodyPresent &&
      input.intent.bodyBytes === binding.bodyBytes && input.intent.bodySha256 === binding.bodySha256,
      'WIRE_SIGNING_REQUEST_MISMATCH');
    need(events['unsigned-response']?.value.status === 402 && !events['signing-input'],
      'WIRE_SIGNING_PHASE_MISMATCH');
    await publish('signing-input', {input, inputSha256:digest(Buffer.from(JSON.stringify(input.intent)))});
  }
  async function signingResult(result) {
    need(events['signing-input'] && !events['signing-result'] && !events['signing-error'],
      'WIRE_SIGNING_PHASE_MISMATCH');
    await publish('signing-result', {inputSha256:events['signing-input'].sha256,
      payload:result, payloadSha256:digest(Buffer.from(JSON.stringify(result)))});
  }
  async function signingError(error) {
    if (!events['signing-input'] || events['signing-result'] || events['signing-error']) return;
    let nativeSigning;
    try { nativeSigning=readNativeSigningDiagnostic(error?.nativeSigning); } catch {}
    await publish('signing-error', {inputSha256:events['signing-input'].sha256,
      code:code(error, 'ORIGINAL_SIGNER_ERROR'), ...(nativeSigning ? {nativeSigning} : {})});
  }
  async function fetch(url, options = {}) {
    const href = new URL(url).href, method = options.method ?? 'GET';
    const currentBody = requestBody(options.body);
    need(href === binding.url && method === binding.method &&
      currentBody.present === binding.bodyPresent && currentBody.bytes.equals(originalBody.bytes),
      'WIRE_REQUEST_BINDING_MISMATCH');
    const headers = headerEntries(options.headers);
    const signature = headers.find(([name]) => name === 'payment-signature')?.[1];
    const leg = signature === undefined ? 'unsigned' : 'signed';
    need(!events[leg + '-request'], 'WIRE_PHASE_ALREADY_RECORDED');
    if (leg === 'signed') {
      const result = events['signing-result'];
      need(result && Buffer.from(JSON.stringify(result.value.payload)).toString('base64') === signature,
        'WIRE_SIGNED_PAYLOAD_MISMATCH');
      const unsigned = events['unsigned-request']?.value;
      need(unsigned && same(headers.filter(([name]) => name !== 'payment-signature'), unsigned.headers),
        'WIRE_REQUEST_HEADERS_CHANGED');
    } else need(!events['signing-input'], 'WIRE_PHASE_ORDER_INVALID');
    const requested = await publish(leg + '-request', {
      url:href, method, headers, bodyPresent:binding.bodyPresent,
      bodyBytes:binding.bodyBytes, bodySha256:binding.bodySha256,
      ...(leg === 'signed' ? {signingResultSha256:events['signing-result'].sha256} : {}),
    });
    // This immutable marker is durable before the original transport may open a
    // socket. Its presence is an attempted dispatch, never proof of delivery.
    await publish(leg + '-dispatch', {requestSha256:requested.sha256});
    let response;
    try { response = await fetchImpl(url, options); }
    catch (error) {
      try { await publish(leg + '-error', {requestSha256:requested.sha256,
        code:code(error, 'ORIGINAL_TRANSPORT_ERROR')}); } catch {}
      throw error;
    }
    try {
      await publish(leg + '-response', {
        requestSha256:requested.sha256, status:response.status,
        statusText:response.statusText, url:response.url || href,
        headers:headerEntries(response.headers),
      });
    } catch (error) {
      // The original request may have been paid. SF31 preserves its signed-leg
      // uncertainty on this error; a failed checkpoint never authorizes retry.
      try { await response.body?.cancel(); } catch {}
      throw error;
    }
    return response;
  }
  return Object.freeze({fetch,signingInput,signingResult,signingError,
    async close(){if(!closed){closed=true;try{await reservations?.close();}finally{await held.close();}}},
    snapshot:() => view(directory,source,events,!closed)});
}

/** Read-only source validation. includeWire is for the original private recovery
 * consumer: it exposes signed authorization bytes and must never be logged,
 * exported to a public artifact, or sent to a different merchant. */
async function checkpointWithLock({cfg, body, includeWire = false}, directory) {
  need(typeof includeWire === 'boolean', 'WIRE_INCLUDE_OPTION_INVALID');
  const source = await originalFile(join(directory,'source.json'),SOURCE_LIMIT);
  const binding = bindingFor(cfg,requestBody(body));
  need(source.value.schema === SCHEMA && same(source.value.binding,binding) &&
    valueHash(source.value.config) === binding.configValueSha256, 'WIRE_SOURCE_BINDING_MISMATCH');
  const retainedBody = source.value.requestBodyBase64;
  need(retainedBody === null ? !binding.bodyPresent :
    typeof retainedBody === 'string' && binding.bodyPresent &&
      Buffer.from(retainedBody,'base64').length === binding.bodyBytes &&
      digest(Buffer.from(retainedBody,'base64')) === binding.bodySha256, 'WIRE_BODY_BINDING_MISMATCH');
  const events = Object.create(null);
  for (const name of EVENTS) {
    const path = join(directory,name+'.json');
    if (!await exists(path)) continue;
    const event = await originalFile(path,RECORD_LIMIT), value = event.value;
    need(value.schema === SCHEMA && value.intentId === binding.intentId &&
      value.sourceSha256 === source.sha256 && value.phase === name &&
      Number.isFinite(Date.parse(value.recordedAt)), 'WIRE_RECORD_BINDING_MISMATCH');
    events[name] = event;
  }
  for (const leg of ['unsigned','signed']) {
    const request = events[leg+'-request'];
    for (const suffix of ['dispatch','response','error']) {
      const event = events[leg+'-'+suffix];
      need(!event || request && event.value.requestSha256 === request.sha256,
        'WIRE_REQUEST_RECORD_MISMATCH');
      if (suffix !== 'dispatch') need(!event || events[leg+'-dispatch'], 'WIRE_DISPATCH_RECORD_MISSING');
    }
    need(!(events[leg+'-response'] && events[leg+'-error']), 'WIRE_CONTRADICTORY_RESPONSE');
    if (request) need(request.value.url === binding.url && request.value.method === binding.method &&
      request.value.bodyPresent === binding.bodyPresent && request.value.bodyBytes === binding.bodyBytes &&
      request.value.bodySha256 === binding.bodySha256, 'WIRE_REQUEST_BINDING_MISMATCH');
  }
  const input=events['signing-input'],signed=events['signing-result'],signedRequest=events['signed-request'];
  if (input) need(events['unsigned-response']?.value.status === 402 &&
    input.value.input?.intent?.intentId === binding.intentId &&
    input.value.input.intent.url === binding.url && input.value.input.intent.method === binding.method &&
    input.value.input.intent.bodyPresent === binding.bodyPresent &&
    input.value.input.intent.bodyBytes === binding.bodyBytes &&
    input.value.input.intent.bodySha256 === binding.bodySha256 &&
    digest(Buffer.from(JSON.stringify(input.value.input.intent))) === input.value.inputSha256,
    'WIRE_SIGNING_RECORD_MISMATCH');
  if (signed) need(input && signed.value.inputSha256 === input.sha256 &&
    digest(Buffer.from(JSON.stringify(signed.value.payload))) === signed.value.payloadSha256,
    'WIRE_SIGNATURE_RECORD_MISMATCH');
  if (events['signing-error']) {
    const errorRecord=events['signing-error'].value;
    need(input && !signed && errorRecord.inputSha256 === input.sha256, 'WIRE_SIGNING_RECORD_MISMATCH');
    if (Object.hasOwn(errorRecord,'nativeSigning')) need(
      readNativeSigningDiagnostic(errorRecord.nativeSigning) !== undefined,
      'WIRE_SIGNING_DIAGNOSTIC_INVALID');
  }
  if (signedRequest) need(signed && signedRequest.value.signingResultSha256 === signed.sha256 &&
    signedRequest.value.headers.find(([name]) => name === 'payment-signature')?.[1] ===
      Buffer.from(JSON.stringify(signed.value.payload)).toString('base64') &&
    same(signedRequest.value.headers.filter(([name]) => name !== 'payment-signature'),
      events['unsigned-request']?.value.headers), 'WIRE_SIGNED_PAYLOAD_MISMATCH');
  const snapshot=view(directory,source,events);
  if(!includeWire) return snapshot;
  // Private capabilities remain directly accessible to the original recovery
  // consumer, while normal JSON/console projections expose only the snapshot.
  return Object.defineProperties({snapshot},{
    source:{value:source.value},
    events:{value:Object.fromEntries(Object.entries(events).map(([name,item]) => [name,item.value]))},
  });
}

export async function readAttemptWireCheckpoint({cfg, body, includeWire = false}) {
  need(typeof includeWire === 'boolean', 'WIRE_INCLUDE_OPTION_INVALID');
  const directory = wirePath(cfg);
  if (!await exists(directory)) return null;
  await privateDirectory(cfg.evidenceDir, {create:false});
  await privateDirectory(directory, {create:false});
  const held=await ownership(directory,false);
  if(!held) return {schema:SCHEMA,intentId:cfg.operation.intentId,directory,
    state:'WRITER_ACTIVE',writerActive:true};
  try { return await checkpointWithLock({cfg,body,includeWire},directory); }
  finally { await held.close(); }
}


const PREAPPROVAL_WIRE = 'stellar-forge.sf88.preapproval-wire.v1';
const HASH = /^[a-f0-9]{64}$/;
const HISTORY_LIMIT = 262144;
const wireCheck = signal => {
  need(signal === undefined || signal instanceof AbortSignal,'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted,'OPERATION_ABORTED_BEFORE_START');
};
function checkpointHash(value) {
  const {sha256,...body}=value;
  return valueHash(body);
}
function missingWire(cfg,body) {
  const value={schema:PREAPPROVAL_WIRE+'.checkpoint',directory:wirePath(cfg),
    binding:bindingFor(cfg,body),exists:false,state:'WIRE_DIRECTORY_ABSENT',files:[]};
  return {...value,sha256:checkpointHash(value)};
}
async function inventoryFile(directory,name) {
  need(name==='active.lock' || name==='source.json' || EVENTS.some(event=>name===event+'.json') ||
    /^\.write-[a-f0-9-]+$/.test(name),'PREAPPROVAL_WIRE_UNKNOWN_MEMBER');
  const path=join(directory,name),fd=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
  try {
    const before=await fd.stat();
    need(before.isFile() && before.size<=SOURCE_LIMIT && !(before.mode&0o077) &&
      (!process.getuid || before.uid===process.getuid()),'WIRE_PRIVATE_FILE_REQUIRED');
    const raw=await fd.readFile(),after=await fd.stat(),named=await lstat(path);
    need(raw.length===before.size && before.dev===after.dev && before.ino===after.ino &&
      before.size===after.size && before.mtimeMs===after.mtimeMs && before.ctimeMs===after.ctimeMs &&
      named.dev===after.dev && named.ino===after.ino && !named.isSymbolicLink(),
      'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    return {name,bytes:raw.length,sha256:digest(raw),device:before.dev,inode:before.ino};
  } finally {await fd.close();}
}
async function releaseUnpublishedWireCapacity(directory,checkpoint) {
  for(const expected of checkpoint.files) {
    if(!/^\.write-[a-f0-9-]+$/.test(expected.name))continue;
    // A killed original Store writer cannot close its preallocated future
    // checkpoint slots. Retain each exact inode and all logical bytes while
    // releasing only its abandoned KEEP_SIZE allocation beyond logical EOF.
    need(same(await inventoryFile(directory,expected.name),expected),
      'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    const path=join(directory,expected.name);
    const fd=await open(path,constants.O_RDWR|(constants.O_NOFOLLOW??0));
    try {
      const before=await fd.stat(),named=await lstat(path);
      need(before.isFile() && !named.isSymbolicLink() && !(before.mode&0o077) &&
        (!process.getuid || before.uid===process.getuid()) &&
        before.dev===expected.device && before.ino===expected.inode &&
        before.size===expected.bytes && named.dev===before.dev && named.ino===before.ino,
        'PREAPPROVAL_WIRE_SOURCE_CHANGED');
      await fd.truncate(expected.bytes);
      await fd.sync();
      const raw=await fd.readFile(),after=await fd.stat(),finalName=await lstat(path);
      need(raw.length===expected.bytes && digest(raw)===expected.sha256 &&
        after.dev===before.dev && after.ino===before.ino && after.size===before.size &&
        finalName.dev===after.dev && finalName.ino===after.ino && !finalName.isSymbolicLink(),
        'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    } finally {await fd.close();}
  }
}
async function captureWire(cfg,body,directory,held) {
  const before=await lstat(directory);
  need(before.isDirectory() && !before.isSymbolicLink(),'WIRE_PRIVATE_DIRECTORY_REQUIRED');
  const names=(await readdir(directory)).sort();
  need(names.length<=64,'PREAPPROVAL_WIRE_INVENTORY_LIMIT');
  if(!held) {
    need(names.length===0,'PREAPPROVAL_WIRE_LOCK_REQUIRED');
    const value={schema:PREAPPROVAL_WIRE+'.checkpoint',directory:wirePath(cfg),
      binding:bindingFor(cfg,body),exists:true,directoryIdentity:{device:before.dev,inode:before.ino},
      lockIdentity:null,state:'EMPTY_BEFORE_LOCK',files:[]};
    return {...value,sha256:checkpointHash(value)};
  }
  const lock=await held.stat(),namedLock=await lstat(join(directory,'active.lock'));
  need(lock.dev===namedLock.dev && lock.ino===namedLock.ino,'WIRE_LOCK_CHANGED');
  const files=[];
  for(const name of names)files.push(await inventoryFile(directory,name));
  need(files.reduce((sum,file)=>sum+file.bytes,0)<=16*1024*1024,'PREAPPROVAL_WIRE_INVENTORY_LIMIT');
  need(!names.some(name=>name.startsWith('signing-')||name.startsWith('signed-')),
    'PREAPPROVAL_WIRE_SIGNING_OR_DISPATCH_RECORDED');
  let state='SOURCE_NOT_RETAINED',sourceSha256=null;
  if(names.includes('source.json')) {
    const checkpoint=await checkpointWithLock({cfg,body:body.present?body.bytes:undefined},directory);
    need(!checkpoint.signingEntered && !checkpoint.signedDispatchRecorded &&
      !checkpoint.signedResponseRecorded,'PREAPPROVAL_WIRE_SIGNING_OR_DISPATCH_RECORDED');
    state=checkpoint.state;sourceSha256=checkpoint.sourceSha256;
  } else need(!names.some(name=>EVENTS.some(event=>name===event+'.json')),
    'PREAPPROVAL_WIRE_SOURCE_MISSING');
  const after=await lstat(directory),afterNames=(await readdir(directory)).sort();
  need(before.dev===after.dev && before.ino===after.ino && same(names,afterNames),
    'PREAPPROVAL_WIRE_SOURCE_CHANGED');
  const value={schema:PREAPPROVAL_WIRE+'.checkpoint',directory:wirePath(cfg),
    binding:bindingFor(cfg,body),exists:true,directoryIdentity:{device:before.dev,inode:before.ino},
    lockIdentity:{device:lock.dev,inode:lock.ino},state,sourceSha256,files};
  return {...value,sha256:checkpointHash(value)};
}
function matchingCheckpoint(expected,actual,{allowCreatedLock=false}={}) {
  if(same(expected,actual))return true;
  return allowCreatedLock && expected?.state==='EMPTY_BEFORE_LOCK' && actual?.state==='SOURCE_NOT_RETAINED' &&
    same(expected.binding,actual.binding) && same(expected.directoryIdentity,actual.directoryIdentity) &&
    expected.directory===actual.directory && actual.files.length===1 &&
    actual.files[0].name==='active.lock' && actual.files[0].bytes===0;
}
async function acquireWire(cfg,body,{createMissingLock=false}={}) {
  const directory=wirePath(cfg);
  if(!await exists(directory))return {held:null,checkpoint:missingWire(cfg,body)};
  await privateDirectory(directory,{create:false});
  const hasLock=await exists(join(directory,'active.lock'));
  if(!hasLock) {
    const empty=await captureWire(cfg,body,directory,null);
    if(!createMissingLock)return {held:null,checkpoint:empty};
  }
  const held=await ownership(directory,createMissingLock);
  need(held,'PREAPPROVAL_WIRE_WRITER_ACTIVE');
  try{return {held,checkpoint:await captureWire(cfg,body,directory,held)};}
  catch(error){await held.close();throw error;}
}
/** Read only: select the complete inactive original wire, including unpublished
 * atomic-write inodes. Unsigned requests are retained; every signer/signed phase
 * and every active original writer makes this same-intent path ineligible. */
export async function inspectPreapprovalWireCheckpoint({cfg,body}) {
  const frozen=JSON.parse(JSON.stringify(cfg)),originalBody=requestBody(body);
  const selected=await acquireWire(frozen,originalBody);
  try{return selected.checkpoint;}finally{await selected.held?.close();}
}
function historyOptions({cfg,body,historyDirectory,planSha256,sourceAttemptSha256,expectedCheckpoint}) {
  const frozen=JSON.parse(JSON.stringify(cfg)),originalBody=requestBody(body);
  const directory=absolute(historyDirectory);
  need(HASH.test(planSha256??'') && HASH.test(sourceAttemptSha256??'') &&
    directory.endsWith('/preapproval-history/'+sourceAttemptSha256),
    'PREAPPROVAL_WIRE_PLAN_REQUIRED');
  const expected=expectedCheckpoint===undefined?undefined:JSON.parse(jsonBytes(expectedCheckpoint));
  if(expected)need(expected.schema===PREAPPROVAL_WIRE+'.checkpoint' &&
    expected.sha256===checkpointHash(expected) && same(expected.binding,bindingFor(frozen,originalBody)) &&
    expected.directory===wirePath(frozen),'PREAPPROVAL_WIRE_SELECTION_CHANGED');
  return {cfg:frozen,body:originalBody,directory,planSha256,sourceAttemptSha256,expected,
    selectionPath:join(directory,'wire-selection.json'),receiptPath:join(directory,'wire-retirement.json'),
    archiveDirectory:join(directory,'original-wire')};
}
function validateSelection(value,options) {
  need(value?.schema===PREAPPROVAL_WIRE+'.selection' &&
    value.intentId===options.cfg.operation.intentId && value.planSha256===options.planSha256 &&
    value.sourceAttemptSha256===options.sourceAttemptSha256 &&
    value.directory===options.directory && value.archiveDirectory===options.archiveDirectory &&
    value.checkpoint?.sha256===checkpointHash(value.checkpoint) &&
    value.checkpoint.directory===wirePath(options.cfg) &&
    same(value.checkpoint.binding,bindingFor(options.cfg,options.body)) &&
    (!options.expected || matchingCheckpoint(options.expected,value.checkpoint,{allowCreatedLock:true})),
    'PREAPPROVAL_WIRE_SELECTION_CHANGED');
  const check=value.originalVerification;
  need(check?.schema==='stellar-forge.node-preapproval-recovery.v1' &&
    check.intentId===value.intentId && check.planSha256===value.planSha256 &&
    check.processProof?.schema==='stellar-forge.node-preapproval-process-proof.v1' &&
    check.processProof.outcome==='ORIGINAL_ATTEMPT_PROCESS_ABSENT' &&
    check.processProof.intentId===value.intentId &&
    check.processProof.attemptSha256===value.sourceAttemptSha256 &&
    check.originalLedgerCheck?.outcome==='ABSENT_FROM_AUTHENTICATED_ORIGINAL_LEDGER' &&
    check.originalLedgerCheck.intentId===value.intentId &&
    check.originalLedgerCheck.ledger===options.cfg.operator.ledger &&
    check.originalLedgerCheck.reservationsForIntent===0,
