  const release = await lockPrivateDirectory({ directory: dir, filename: '.catalog-writer.lock',
    namespace: 'sf88-catalog', busyCode: 'CATALOG_WRITER_ACTIVE_OR_STALE_SOCKET',
    unavailableCode: 'CATALOG_LOCK_UNAVAILABLE' });
