      observation: 'PARSED_PAGES_NOT_ATOMIC_PROVIDER_SNAPSHOT', status: 'ACQUIRING',
      pages: [], rows: 0, total: null, sourceEnvelope: null,
      nextOffset: requestIdentity.request.offset, error: null };
