    const child=spawn(selected.python,['-I','-B',WORKER],{shell:false,
      env:{LANG:'C.UTF-8',LC_ALL:'C.UTF-8',PATH:process.env.PATH??'/usr/bin:/bin'},
      stdio:['pipe','pipe','pipe']});
