  need(typeof python === 'string' && resolve(python) === python, 'INITIALIZATION_PYTHON_REQUIRED');
  need(await realpath(dirname(directory)) === dirname(directory), 'INITIALIZATION_PARENT_PATH_AMBIGUOUS');
  let created = false;
